insomnia.test("Um item por dia do período", () => {
  const dia = 24 * 3600 * 1000;
  const n = Math.round((Date.parse(insomnia.environment.get('ate')) - Date.parse(insomnia.environment.get('de'))) / dia) + 1;
  insomnia.expect(corpo.data.granularidade).to.eql('dia');
  insomnia.expect(corpo.data.serie.length).to.eql(n);
});

insomnia.test("Período anterior tem o mesmo número de dias e termina um dia antes de `de`", () => {
  const dia = 24 * 3600 * 1000;
  const p = corpo.data.periodo_anterior;
  const nAtual = Math.round((Date.parse(corpo.data.periodo.ate) - Date.parse(corpo.data.periodo.de)) / dia) + 1;
  const nAnt = Math.round((Date.parse(p.ate) - Date.parse(p.de)) / dia) + 1;
  insomnia.expect(nAnt).to.eql(nAtual);
  insomnia.expect(Date.parse(corpo.data.periodo.de) - Date.parse(p.ate)).to.eql(dia);
});

